    public static function key(string $source):string{return 'invoice_entry_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array{$english=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as$source=>$translated)$out[self::key($source)]=$english?$translated:$source;return$out;}
    public static function text(string $source,array $messages,array $values=[]):string{$text=$messages[self::key($source)]??$source;foreach($values as$key=>$value)$text=str_replace('{'.$key.'}',(string)$value,$text);return$text;}
    /** Only known native failure messages enter this translator; submitted values stay literal. */
    public static function error(string $source,array $messages):string
    {
        if(preg_match('/\APosition ([1-9][0-9]?): (.+)\z/Ds',$source,$parts))return self::text('Position {number}',$messages,['number'=>$parts[1]]).': '.self::error($parts[2],$messages);
        return self::text($source,$messages);
    }
    public static function client(array $messages):array{$out=[];foreach(self::ENGLISH as$source=>$translated)$out[$source]=$messages[self::key($source)]??$source;return$out;}
}
